#define DIVS 10.0
#define HMUL 0.5

vec3 hsv2rgb(float h, float s, float v) {
    return mix(vec3(1), clamp(abs(mod(h*6.+vec3(0,4,2),6.)-3.)-1.,0.,1.), s) * v;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 pt = fragCoord.xy / iResolution.xy;  // normalize 0..1
    pt.x *= iResolution.x / iResolution.y;  // fix aspect-ratio
    pt.y -= 1.;  // move origin on top-left corner
    float sm = DIVS / iResolution.y;  // smoothness

    float aStep = (length(pt) - iTime * .15) * DIVS;
    float iStep = floor(aStep);
    float fStep = fract(aStep);

    float h1 = iStep / DIVS * HMUL;
    float h2 = (iStep + 1.) / DIVS * HMUL;

    vec3 color = mix(
            hsv2rgb(h1, 1., 1.),  // color 1
            hsv2rgb(h2, 1., smoothstep(.1, 1., fStep)),  // color 2
            smoothstep(.5, .5 + sm, fStep));
    fragColor = vec4(color, 1.);
}
